package net.zartra.gui;
import static org.junit.Assert.*;import java.nio.file.*;import org.junit.Test;
public class NaturalShiftTransferTest {private String s()throws Exception{return new String(Files.readAllBytes(Paths.get("src/main/java/net/zartra/gui/GuiService.java")),"UTF-8");}@Test public void lowerShiftUsesDeterministicVirtualTransfer()throws Exception{String s=s();assertTrue(s.contains("shiftLowerToEditor"));assertTrue(s.contains("if(e.isShiftClick()){shiftLowerToEditor"));assertTrue(s.contains("similar(existing,MenuItem.runtime(source))"));assertTrue(s.contains("for(int n=0;n<top.getSize()"));assertTrue(s.contains("checkpoint(p,d)"));assertTrue(s.contains("ItemStack source=liveLower(p,captured.slot)"));assertTrue(s.contains("setLiveLower(p,captured.slot"));}@Test public void confirmationsUseEmeraldAndRedstone()throws Exception{String s=s();assertTrue(s.contains("Material.EMERALD"));assertTrue(s.contains("Material.REDSTONE"));assertTrue(s.contains("&aConfirm Reset"));assertTrue(s.contains("&aSave Changes"));assertTrue(s.contains("Material.BARRIER"));}@Test public void pickerReplacementHasTransitionGuard()throws Exception{String s=s();assertTrue(s.contains("leatherPickerTransitions"));assertTrue(s.contains("leatherPickerTransitions.add"));assertTrue(s.contains("consumeLeatherPickerTransition"));}}